SELECT 'sheet_catalog' AS table_name, (SELECT COUNT(*) FROM pragma_table_info('sheet_catalog')) AS column_count, (SELECT GROUP_CONCAT(name, ',') FROM (SELECT name FROM pragma_table_info('sheet_catalog') ORDER BY cid)) AS column_names, (SELECT COUNT(*) FROM sqlite_schema WHERE type='index' AND name='idx_sheet_catalog_status' AND tbl_name='sheet_catalog') AS expected_index_exists, 0 AS expected_fk_exists
UNION ALL
SELECT 'sheet_rows', (SELECT COUNT(*) FROM pragma_table_info('sheet_rows')), (SELECT GROUP_CONCAT(name, ',') FROM (SELECT name FROM pragma_table_info('sheet_rows') ORDER BY cid)), (SELECT COUNT(*) FROM sqlite_schema WHERE type='index' AND name='idx_sheet_rows_sheet_row' AND tbl_name='sheet_rows'), (SELECT COUNT(*) FROM pragma_foreign_key_list('sheet_rows') WHERE "table"='sheet_catalog' AND "from"='sheet_name' AND "to"='sheet_name' AND on_delete='CASCADE')
UNION ALL
SELECT 'sheet_migration_runs', (SELECT COUNT(*) FROM pragma_table_info('sheet_migration_runs')), (SELECT GROUP_CONCAT(name, ',') FROM (SELECT name FROM pragma_table_info('sheet_migration_runs') ORDER BY cid)), (SELECT COUNT(*) FROM sqlite_schema WHERE type='index' AND name='idx_sheet_migration_runs_sheet' AND tbl_name='sheet_migration_runs'), 0;